// Package sqlmigration is the logic of the migration helpers, migy (MySQL) and pigy (PostgreSQL).
//
// It knows neither DSNs nor command line flags: it takes a *sqlx.DB, an
// io.Writer for the progress, and a dialect.Dialect.
package sqlmigration

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/jmoiron/sqlx"

	"github.com/makiuchi-d/sql-migration/dialect"
)

// signature returns the first line of the generated files.
func signature(name string) string {
	return fmt.Sprintf("-- Generated by %s (https://github.com/makiuchi-d/sql-migration)", name)
}

func info(w io.Writer, a ...any) {
	fmt.Fprintln(w, a...)
}

// applyFile executes all statements in the SQL file.
func applyFile(db sqlx.Execer, d dialect.Dialect, path string) error {
	input, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	for s := range d.Statements(input) {
		if _, err := db.Exec(s); err != nil {
			return fmt.Errorf("%s: %w", filepath.Base(path), err)
		}
	}
	return nil
}

func applyFiles(w io.Writer, db sqlx.Execer, d dialect.Dialect, dir string, files ...string) error {
	for _, f := range files {
		info(w, "applying:", f)
		if err := applyFile(db, d, filepath.Join(dir, f)); err != nil {
			return err
		}
	}
	return nil
}

// OpenDumpFile returns a temporary database where the dump file is applied.
func OpenDumpFile(d dialect.Dialect, path string) (*sqlx.DB, error) {
	db, err := d.OpenTemp()
	if err != nil {
		return nil, err
	}
	if err := applyFile(db, d, path); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}
